contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _v1, uint _v2) public {
        // Before initialization, SetMinSum freely updates MinSum.
        c.SetMinSum(_v1); if (__ESBMC_reverted()) return;
        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        // After initialization, SetMinSum must revert and leave MinSum unchanged.
        bool reverted;
        c.SetMinSum(_v2); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && minBefore == _v1 && c.MinSum() == _v1);
    }
}

