// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 _v1, uint256 _v2) internal {
        try c.SetMinSum(_v1) {} catch { return; }
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(_v2) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && minBefore == _v1 && c.MinSum() == _v1);
    }

    function testFuzz_run(uint256 _v1, uint256 _v2) public {
        _run(_v1, _v2);
    }

    receive() external payable {}
}
